INSERT INTO atividade_avaliativa (id, cenario_json, criada_em, data_entrega, descricao, gabarito_estado_json, modo, pontuacao_maxima, status, titulo, turma_id) VALUES (9300002, '{"versao": 1, "linhas": 6, "colunas": 6, "inicio": {"linha": 5, "coluna": 0}, "destino": {"linha": 0, "coluna": 5}, "obstaculos": [{"linha": 2, "coluna": 1}, {"linha": 2, "coluna": 2}, {"linha": 3, "coluna": 3}, {"linha": 1, "coluna": 3}], "blocosPermitidos": ["robo_mover", "robo_repetir"], "maxBlocos": 8}', '2026-10-28 10:00:00', '2027-07-15T23:59:00', '<p>Leve o robô até a bandeira desviando dos obstáculos; use poucos blocos.</p>', NULL, 'JOGO_ROBO', 10, 'PUBLICADA', 'Jogo do Robô: atravesse o labirinto', 9100001) ON CONFLICT DO NOTHING
@@FIM@@
