INSERT INTO pagina_licao (id, conteudo_json, ordem, tipo, titulo, licao_id) VALUES (9720001, '{"html":"<h2>O que é um algoritmo?</h2><p>Um algoritmo é uma <strong>sequência de passos</strong> para resolver um problema&nbsp;&mdash; como uma receita de bolo; cada passo vem depois do outro.</p><ul><li>Passos claros;</li><li>Ordem certa;</li><li>Um objetivo no final.</li></ul>"}', 0, 'TEXTO', 'O que é um algoritmo?', 9700001) ON CONFLICT DO NOTHING
@@FIM@@
